/// <summary>
/// The <c>METExciseRegisterReceiptVarianceContract</c> class is the contract class for the <c>METExciseRegisterUnderbondReceiptVarianceReport</c> report
/// </summary>
[DataContract]
class METExciseRegisterReceiptVarianceContract implements SysOperationValidatable
{
    FromDate     fromDate;
    ToDate       toDate;
    VendAccount  vendorId;

}

Method.Source:
[DataMember('FromDate'),
SysOperationLabelAttribute(literalStr("@SYS5209")),
SysOperationHelpTextAttribute(literalStr("@SYS26930")),
SysOperationDisplayOrderAttribute('1')]
public FromDate parmFromDate(FromDate _fromDate = fromDate)
{
    fromDate = _fromDate;
    return fromDate;
}

[DataMember('ToDate'),
SysOperationLabelAttribute(literalStr("@SYS14656")),
SysOperationHelpTextAttribute(literalStr("@SYS26929")),
SysOperationDisplayOrderAttribute('2')]
public ToDate parmToDate(ToDate _toDate = toDate)
{
    toDate = _toDate;
    return toDate;
}

[DataMember('VendorId'),
SysOperationLabel('@SYS14048'),
SysOperationDisplayOrderAttribute('3')]
public VendAccount parmVendorId(VendAccount _vendorId = vendorId)
{
    vendorId = _vendorId;
    return vendorId;
}

    /// <summary>
    ///    Validates the parameters.
    /// </summary>
    /// <returns>
    ///    true if successful; otherwise, false.
    /// </returns>
    public boolean validate()
    {
        boolean ret = true;

        if(!fromDate)
        {
            ret = checkFailed("@SYS91557");
        }

        if(!toDate)
        {
            ret = checkFailed("@SYS90868");
        }

        if (fromDate && fromDate && fromDate > toDate)
        {
            ret = checkFailed("@SYS16982");
        }

        if(vendorId)
        {
            VendTable vendTable;
            select firstonly AccountNum from vendTable
                where vendTable.AccountNum == vendorId;
            if(!vendTable.AccountNum)
            {
                ret = checkFailed(strFmt("@SYS17184",vendorId));
            }
        }
        return ret;
    }
